//! Goldens from the reference tmux 3.8, regenerated by
//! `tests/term_features_cases.py` into `golden/cases.tsv`: for each terminal
//! and configuration, `#{client_termfeatures}`, `#{client_colours}` and
//! which capabilities (`#{Ic:name}`) the attached client's terminal has.

use super::{Cap, Term};

const CASES: &str = include_str!("golden/cases.tsv");

/// The defaults of `terminal-features` and `terminal-overrides`
/// (options-table.c); the rows' items are `[10+i]` after them.
const DEFAULT_FEATURES: [&str; 3] = [
    "xterm*:clipboard:ccolour:cstyle:focus:title",
    "screen*:title",
    "rxvt*:ignorefkeys",
];
const DEFAULT_OVERRIDES: [&str; 1] = ["linux*:AX@"];

fn items(defaults: &[&str], column: &str) -> Vec<String> {
    let mut all: Vec<String> = defaults.iter().map(|s| (*s).to_owned()).collect();
    if column != "-" {
        all.extend(column.split('~').map(str::to_owned));
    }
    all
}

/// What the reference printed for a terminal, from our model.
fn describe(term: &Term) -> String {
    let caps: Vec<&str> = Cap::ALL
        .into_iter()
        .filter(|c| term.has(*c))
        .map(Cap::name)
        .collect();
    format!(
        "{}|{}|{}",
        term.features().list(),
        term.colours(),
        caps.join(" ")
    )
}

#[test]
fn every_case_matches_the_reference() {
    let mut rows = 0;
    for line in CASES.lines().filter(|l| !l.starts_with('#')) {
        let f: Vec<&str> = line.split('\t').collect();
        let [name, colorterm, client, features, overrides, expected] = f[..] else {
            panic!("malformed row {line:?}");
        };
        let client: Vec<String> = if client == "-" {
            Vec::new()
        } else {
            client.split(' ').map(str::to_owned).collect()
        };
        let term = Term::open(
            name,
            &client,
            (colorterm != "-").then_some(colorterm),
            &items(&DEFAULT_FEATURES, features),
            &items(&DEFAULT_OVERRIDES, overrides),
        )
        .unwrap_or_else(|| panic!("unknown terminal in {line:?}"));
        assert_eq!(describe(&term), expected, "row {line:?}");
        rows += 1;
    }
    assert!(rows > 150, "{rows} rows");
}

/// tty-keys.c `tty_keys_sync`: a DECRPM reply adds `sync` after the terminal
/// was created. The reference's list after the same query is the one with
/// `-T sync` (the feature only changes the list and `Sync`).
#[test]
fn a_late_sync_reply_adds_the_feature_and_capability() {
    let mut term = Term::open(
        "xterm-256color",
        &[],
        None,
        &items(&DEFAULT_FEATURES, "-"),
        &items(&DEFAULT_OVERRIDES, "-"),
    )
    .unwrap();
    assert!(!term.has(Cap::Sync));
    term.sync_supported();
    assert_eq!(
        describe(&term),
        "bpaste,ccolour,clipboard,cstyle,focus,sync,title|16|Sync Ss Se Ms tsl fsl"
    );
}

/// tty-keys.c's DA, DA2 and XTVERSION parsers: what a reply to the startup
/// queries adds to an `xterm-256color` client (tty-features.c
/// `tty_default_features`). From tmux 3.8, isolated: `new -d cat; set -g
/// extended-keys on`, attach under a PTY that answers the queries with
/// REPLY, then `lsc -F '#{client_termfeatures}|#{client_termtype}'` and
/// whether `\e[>4;2m` (Eneks) was written (tmp da.py).
#[test]
fn device_attribute_replies_add_features() {
    enum Reply {
        Da(&'static [u32]),
        Da2(u32),
        Xda(&'static str),
    }
    let cases = [
        (
            Reply::Xda("ghostty 1.2.3"),
            "256,bpaste,ccolour,clipboard,hyperlinks,cstyle,extkeys,focus,margins,mouse,osc7,overline,progressbar,RGB,strikethrough,sync,title,usstyle|ghostty 1.2.3",
            true,
        ),
        (
            Reply::Xda("XTerm(390)"),
            "256,bpaste,ccolour,clipboard,cstyle,extkeys,focus,mouse,RGB,strikethrough,title|XTerm(390)",
            true,
        ),
        (
            Reply::Xda("foot(1.2)"),
            "256,bpaste,ccolour,clipboard,hyperlinks,cstyle,extkeys,focus,mouse,osc7,RGB,strikethrough,sync,title,usstyle|foot(1.2)",
            true,
        ),
        (
            Reply::Xda("Rio 0.2"),
            "256,bpaste,ccolour,clipboard,hyperlinks,cstyle,focus,mouse,osc7,overline,progressbar,RGB,strikethrough,sync,title,usstyle|Rio 0.2",
            false,
        ),
        (
            Reply::Xda("kitty(0.3)"),
            "bpaste,ccolour,clipboard,cstyle,focus,title|kitty(0.3)",
            false,
        ),
        (
            Reply::Da(&[62, 4, 21, 28, 52]),
            "bpaste,ccolour,clipboard,cstyle,focus,margins,rectfill,sixel,title|",
            false,
        ),
        (
            Reply::Da(&[64, 52]),
            "bpaste,ccolour,clipboard,cstyle,focus,title|",
            false,
        ),
        (
            Reply::Da(&[1, 2]),
            "bpaste,ccolour,clipboard,cstyle,focus,title|",
            false,
        ),
        (
            Reply::Da(&[62, 308]),
            "bpaste,ccolour,clipboard,cstyle,focus,title|",
            false,
        ),
        (
            Reply::Da2(84),
            "256,bpaste,ccolour,clipboard,hyperlinks,cstyle,extkeys,focus,mouse,overline,progressbar,RGB,strikethrough,title,usstyle|",
            true,
        ),
        (
            Reply::Da2(77),
            "256,appesc,bpaste,ccolour,clipboard,cstyle,extkeys,focus,margins,mouse,overline,RGB,strikethrough,title,usstyle|",
            true,
        ),
        (
            Reply::Da2(85),
            "256,bpaste,ccolour,clipboard,cstyle,focus,ignorefkeys,mouse,title|",
            false,
        ),
        (
            Reply::Da2(1),
            "bpaste,ccolour,clipboard,cstyle,focus,title|",
            false,
        ),
    ];
    for (reply, want, eneks) in cases {
        let mut term = Term::open(
            "xterm-256color",
            &[],
            None,
            &items(&DEFAULT_FEATURES, "-"),
            &items(&DEFAULT_OVERRIDES, "-"),
        )
        .unwrap();
        match reply {
            Reply::Da(p) => term.device_attributes(p),
            Reply::Da2(p) => term.secondary_device_attributes(p),
            Reply::Xda(t) => term.extended_device_attributes(t),
        }
        assert_eq!(
            format!("{}|{}", term.features().list(), term.term_type()),
            want
        );
        assert_eq!(term.enable_extended_keys().is_some(), eneks, "{want}");
        assert_eq!(term.disable_extended_keys().is_some(), eneks, "{want}");
    }
}
